import { Currency, type Money, type DiscountRule } from "./types.ts";

export function applyDiscount(price: number, rate: number, currency: string): number {
  return price * (1 - rate);
}

export function formatMoney(amount: Money, currency: Currency = Currency.USD): string {
  return `${currency} ${amount.toFixed(2)}`;
}

export class PriceRule implements DiscountRule {
  apply(price: Money): Money { return applyDiscount(price, 0.1); }
}

export class SeasonalRule extends PriceRule {
  apply(price: Money): Money { return applyDiscount(price, 0.2); }
}

export const defaultDiscount = applyDiscount;

cart.ts:
import { Currency, type CartItem } from "./types.ts";
import { applyDiscount } from "./pricing.ts";

export class Cart {
  items: CartItem[] = [];

  add(item: CartItem): void {
    this.items = [...this.items, item];
  }

  total(): number {
    let amount = 0;
    for (const item of this.items) amount += item.price * item.quantity;
    return applyDiscount(amount, 0.1);
  }

  discountedTotal(): number {
    let amount = 0;
    for (const item of this.items) amount += item.price * item.quantity;
    return applyDiscount(amount, 0.15, Currency.USD);
  }
}

checkout.ts:
import { Cart } from "./cart.ts";
import { formatMoney } from "./pricing.ts";

export function checkout(cart: Cart): string {
  return formatMoney(cart.total());
}
